#include <iostream>
#include <vector>
#include <string>
using namespace std;

bool extend(int v, int count, int n, const vector<vector<int>>& adj, vector<char>& visited) {
    if (count == n) return true;
    for (int u : adj[v]) {
        if (!visited[u]) {
            visited[u] = 1;
            if (extend(u, count + 1, n, adj, visited)) return true;
            visited[u] = 0;
        }
    }
    return false;
}

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> roads(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> roads[i][j];
        }
    }

    vector<vector<int>> adj(n);
    for (int i = 0; i < m; i++) {
        adj[roads[i][0] - 1].push_back((int)roads[i][1] - 1);
        adj[roads[i][1] - 1].push_back((int)roads[i][0] - 1);
    }
    bool found = false;
    for (int s = 0; s < n && !found; s++) {
        vector<char> visited(n, 0);
        visited[s] = 1;
        if (extend(s, 1, (int)n, adj, visited)) found = true;
    }
    cout << (found ? "yes" : "no") << "\n";

    return 0;
}

